{{
Relationskette/align/handlinks
| TTY
|| {{Mengebed| (P,u, v,w)| (P,u) \in TY| {{op:Totales Differential|\varphi|(P,u)|(v,w)}} {{=}} 0 }} 
| \subseteq | \R^{4n}
|| 
|SZ=.
}}
