{{
Definitionslink
|Prämath=
|Jacobi-Matrix|
|Kontext=|
|SZ=,
}}
die das totale Differential {{math|term= D \varphi |SZ=}}  beschreibt, ist
{{
Math/display|term=
  {{op:Matrix26| {{op:Partielle Ableitung| f | x_1 | P}} | \ldots| {{op:Partielle Ableitung| f | x_n | P}} | 0| \ldots| 0 | \sum_{i {{=}} 1}^n u_i   {{op:Partielle Ableitung|| x_1 }} {{op:Partielle Ableitung| f | x_i | P}} | \ldots | \sum_{i {{=}} 1}^n u_i   {{op:Partielle Ableitung|| x_n }} {{op:Partielle Ableitung| f | x_i | P}} | {{op:Partielle Ableitung| f | x_1 | P}} | \ldots| {{op:Partielle Ableitung| f | x_n | P}} }}
|SZ=.
}}
