{{
mathkor|term1=
P
|und|term2=
u
|SZ=
}}
beziehen, die beiden zusätzlichen Bedingungen an alle Variablen, nämlich
{{
Relationskette/display
| \sum_{j {{=}} 1}^n v_j {{op:Partielle Ableitung| f | x_j | P}}
|| 0
|| 
|| 
|| 
|SZ=
}}
und
{{
Relationskette/display
| \sum_{j {{=}} 1}^n v_j  {{makl| \sum_{i {{=}} 1}^n u_i {{op:Partielle Ableitung|| x_i |}}  {{op:Partielle Ableitung| f | x_j | P}} |}}      + \sum_{k {{=}} 1}^n w_k {{op:Partielle Ableitung| f | x_k | P}}
|| 0
|| 
|| 
|| 
|SZ=.
}}
