|| {{op:Zeilenvektor| s | 0}} + r {{op:Zeilenvektor| {{op:tanh| t |}} | {{op:Bruch| 1 | {{op:cosh| t |}} }} }} 
|| 
|| 
|| 
|SZ=
}}
zu
{{
Relationskette
| s
| \in | \R
||
||
||
|SZ=,
}}
{{
