|| {{op:Bruch| {{op:Skalarprodukt|R(\partial_1 ,\partial_2)\partial_2 | \partial_1 }} | {{op:Skalarprodukt| \partial_1 | \partial_1 }}  {{op:Skalarprodukt| \partial_2 | \partial_2 }}  -{{op:Skalarprodukt| \partial_1 | \partial_2 }}^2  }} 
|| {{op:Bruch| {{op:Skalarprodukt|R(\partial_1 ,\partial_2)\partial_2 | \partial_1 }} | g_{11} g_{22}  -g_{12}^2  }} 
|| -  {{op:Bruch| {{op:Skalarprodukt|R(\partial_1 ,\partial_2)\partial_1 | \partial_2 }} | g_{11} g_{22}  -g_{12}^2  }} 
|| 
|SZ=
}}
Dabei ist gemäß
{{
Faktlink
|Faktseitenname= 
R^n/Offene Menge/Riemannsche Metrik/Levi-Civita-Zusammenhang/Krümmungsoperator/Berechnung/Fakt
|Nr=
|SZ=
}}
{{
Relationskette/display
| R( \partial_1 , \partial_2)( \partial_1)
|| R^1_{121} \partial_1+ R^2_{121} \partial_2
|| 
|| 
|| 
|SZ=.
}}
Dies ergibt
{{
Relationskette/align
| K( \partial_1, \partial_2)
|| - {{op:Bruch| {{op:Skalarprodukt|R(\partial_1 ,\partial_2)\partial_1 | \partial_2 }} | g_{11} g_{22}  -g_{12}^2  }} 
|| - {{op:Bruch| R^1_{121} g_{12}+ R^2_{121} g_{22} | g_{11} g_{22}  -g_{12}^2  }} 
|| 
|| 
|SZ=.
}}
Nach
{{
Faktlink
|Faktseitenname= 
Riemannsche Mannigfaltigkeit/Levi-Civita-Zusammenhang/Krümmungsoperator/Eigenschaften/Fakt
|Nr=4
|SZ=
}}
ist
{{
Relationskette/display
| {{op:Skalarprodukt| R(\partial_1, \partial_1) \partial_1 | \partial_2 }} 
|| R^1_{121}  g_{11}  + R_{121}^2 g_{12}
|| 0
|| 
|| 
|SZ=.
}}
Wir multiplizieren den Zähler der Schnittkrümmung mit {{math|term= g_{11} |SZ=}} und erhalten
{{
Relationskette/align/handlinks
| g_{11}  {{makl| R^1_{121} g_{12}+ R^2_{121} g_{22} |}} 
|| g_{11}  {{makl| R^1_{121} g_{12}+ R^2_{121} g_{22} |}} - g_{12}  {{makl| R^1_{121}  g_{11}  + R_{121}^2 g_{12}  |}} 
|| g_{11} g_{22} R^2_{121} - g_{12}^2 R^2_{121}
|| {{makl| g_{11} g_{22}  - g_{12}^2 |}} R^2_{121}
|| 
|SZ=.
}}
Also ist
{{
Relationskette/display
| K( \partial_1, \partial_2)
|| -  {{op:Bruch| R^2_{121}|g_{11} }} 
|| 
|| 
|| 
|SZ=.
}}
